// The C++ consensus strategy against the Go playbook on one seeded series of 1h
// candles (tests/fixtures/consensus_equivalence.json, generated by
// cpp_equivalence_fixture_test.go): 3h aggregation, indicator windows, votes,
// cooldowns, stops and sizing all have to reproduce the Go fills.
#include "tradingcopilot/v1/run_envelope.pb.h"
#include <gtest/gtest.h>

#include "bars_aggregate.hpp"
#include "consensus_strategy.hpp"

#include "google/protobuf/struct.pb.h"
#include "tradingcopilot/v1/strategy.pb.h"

#include <google/protobuf/util/json_util.h>

#include <fstream>
#include <sstream>

namespace dagobert {
namespace {

using google::protobuf::Struct;

constexpr std::int64_t kHourMs = 3'600'000;
constexpr std::int64_t kBarMs = 10'800'000;

Struct load() {
  std::ifstream in(CONSENSUS_EQUIVALENCE_FIXTURE_PATH);
  std::stringstream text;
  text << in.rdbuf();
  Struct root;
  const auto status =
      google::protobuf::util::JsonStringToMessage(text.str(), &root);
  EXPECT_TRUE(status.ok()) << status.message();
  return root;
}

std::vector<Bar> decision_bars(const Struct &root) {
  std::vector<Bar> source;
  for (const auto &v : root.fields().at("candles").list_value().values()) {
    const auto &c = v.struct_value().fields();
    Bar bar;
    bar.open_ms = static_cast<std::int64_t>(c.at("open_ms").number_value());
    bar.open = c.at("open").number_value();
    bar.high = c.at("high").number_value();
    bar.low = c.at("low").number_value();
    bar.close = c.at("close").number_value();
    bar.volume = c.at("volume").number_value();
    bar.duration_ms = kHourMs;
    source.push_back(std::move(bar));
  }
  return aggregate_bars(source, kHourMs, kBarMs);
}

tradingcopilot::v1::RunEnvelope envelope(const Struct &config, double quote) {
  std::string json;
  EXPECT_TRUE(google::protobuf::util::MessageToJsonString(config, &json).ok());
  tradingcopilot::v1::SignalConsensusConfig payload;
  const auto status =
      google::protobuf::util::JsonStringToMessage(json, &payload);
  EXPECT_TRUE(status.ok()) << status.message();
  tradingcopilot::v1::RunEnvelope out;
  out.set_schema_version(2);
  out.set_label("signal-consensus");
  out.set_initial_quote(quote);
  EXPECT_TRUE(out.mutable_payload()->PackFrom(payload));
  return out;
}

void expect_matches(const std::string &name, const StrategyResult &got,
                    const google::protobuf::Value &expected_list) {
  const auto &expected = expected_list.list_value().values();
  ASSERT_EQ(got.actions.size(), static_cast<std::size_t>(expected.size()))
      << name;
  ASSERT_EQ(got.fills.size(), static_cast<std::size_t>(expected.size()))
      << name;
  for (int i = 0; i < expected.size(); ++i) {
    const auto &e = expected[i].struct_value().fields();
    const auto u = static_cast<std::size_t>(i);
    EXPECT_EQ(got.actions[u].bar_open_ms,
              static_cast<std::int64_t>(e.at("bar_open_ms").number_value()))
        << name << " #" << i;
    EXPECT_EQ(got.actions[u].reason, e.at("reason").string_value())
        << name << " #" << i;
    EXPECT_EQ(got.fills[u].side, e.at("side").string_value())
        << name << " #" << i;
    EXPECT_EQ(got.fills[u].price, e.at("price").number_value())
        << name << " #" << i;
    const double qty = e.at("qty").number_value();
    EXPECT_NEAR(got.fills[u].qty, qty, 1e-9 * std::max(1.0, qty))
        << name << " #" << i;
  }
}

} // namespace

TEST(ConsensusEquivalence, FixtureHasEnoughBars) {
  EXPECT_GE(decision_bars(load()).size(), 500U);
}

TEST(ConsensusEquivalence, MatchesGoPlaybookOnEveryCase) {
  const Struct root = load();
  const std::vector<Bar> bars = decision_bars(root);
  const double quote = root.fields().at("initial_quote").number_value();
  for (const auto &c : root.fields().at("cases").list_value().values()) {
    const auto &fields = c.struct_value().fields();
    const std::string name = fields.at("name").string_value();
    const auto env = envelope(fields.at("config").struct_value(), quote);
    const auto sizing = ConsensusStrategy::sizing_of(env);
    const auto params = ConsensusStrategy::params_of(env);

    ConsensusStrategy batch(env, kBarMs, sizing, params);
    expect_matches(name + " batch", batch.calc_backtest(bars),
                   fields.at("expected"));

    ConsensusStrategy live(env, kBarMs, sizing, params);
    if (name != "volume_ratio_always_one") {
      EXPECT_GE(fields.at("expected").list_value().values_size(), 10) << name;
    }
    StrategyResult streamed;
    for (const Bar &bar : bars) {
      streamed = live.calc_live(bar);
    }
    expect_matches(name + " live", streamed, fields.at("expected"));
  }
}

} // namespace dagobert
